import assert from 'node:assert/strict';
import {elevation,stableReading,clinometer,conditionReview,validateInstrument,parseObservations,CONDITIONS} from '../../dist/school3d/tree/field-core.js';
import {FieldHardware} from '../../dist/school3d/tree/field-hardware.js';
import {geometry,validateRecord,parseRecords,FORMULA,SOURCE} from '../../dist/school3d/tree/quest-core.js';
const near=(a,b)=>assert.ok(Math.abs(a-b)<1e-7,`${a} != ${b}`);
near(elevation(90,0),0);near(elevation(135,0),45);near(elevation(180,45),45);near(elevation(0,0),-90);
assert.throws(()=>elevation(null,0));assert.throws(()=>elevation(45,100));
const now=10000,samples=Array.from({length:20},(_,i)=>({time:now-950+i*50,beta:135,gamma:0}));
const angles=samples.map(s=>({time:s.time,angle:elevation(s.beta,s.gamma)}));
assert.equal(stableReading(angles,now).stable,true);
assert.equal(stableReading(angles,now+2000).stable,false);
assert.equal(stableReading(angles.slice(0,2),now).stable,false);
assert.equal(stableReading(angles.map((s,i)=>({...s,angle:i%2?40:50})),now).stable,false);
const condition={inspected:true,flags:[],notes:'',measurementHeight:1.3};
const instrument={distance:8,eye:1.3,angle:45,level:true,aligned:true,calibrated:true,source:'sensor',capturedAt:'2026-10-29T00:00:00Z',sensor:{zero:0,spread:0,samples},condition};
near(validateInstrument(instrument).height,9.3);
near(clinometer({...instrument,angle:30}).height,8*Math.tan(Math.PI/6)+1.3);
assert.equal(clinometer({...instrument,level:false}).valid,false);
assert.throws(()=>clinometer({...instrument,angle:89}));assert.throws(()=>clinometer({...instrument,distance:0}));
assert.throws(()=>validateInstrument({...instrument,angle:46}));
assert.throws(()=>validateInstrument({...instrument,sensor:{...instrument.sensor,spread:4}}));
assert.equal(conditionReview(condition).requiresReview,false);
for(const flag of Object.keys(CONDITIONS))assert.equal(conditionReview({...condition,flags:[flag]}).requiresReview,true);
assert.equal(conditionReview({...condition,measurementHeight:1.7}).requiresReview,true);
assert.equal(conditionReview({...condition,inspected:false}).requiresReview,true);
assert.throws(()=>conditionReview({...condition,flags:['invented']}));
assert.throws(()=>geometry({mode:'clinometer',instrument:{...instrument,condition:{...condition,flags:['fork_below']}}}));
const r={id:'sensor-record',name:'感測量測樹',species:'樟樹',date:'2026-10-29',height:9.3,circumference:120,group:'broadleaf',coefficients:null,formulaId:FORMULA,sourceUrl:SOURCE,estimatedAt:'2026-10-29T00:00:00Z',measurementMethod:'sensor_clinometer',measurement:{level:true,aligned:true,calibrated:true,instrument},demo:false,platformId:null,location:null};
const valid=validateRecord(r);assert.equal(valid.result.co2Kg,null);
assert.deepEqual(parseRecords(JSON.stringify({version:1,records:[valid]})),[valid]);
assert.throws(()=>validateRecord({...r,measurementMethod:'manual_clinometer'}));
const demoRecord={...r,measurementMethod:'demo_clinometer',measurement:{...r.measurement,instrument:{...instrument,source:'demo',sensor:null}},demo:true};
assert.equal(validateRecord(demoRecord).demo,true);assert.throws(()=>validateRecord({...demoRecord,demo:false}));
const observation={id:'observation',name:'分岔測試',platformId:null,createdAt:'2026-10-29T00:00:00Z',condition:{...condition,flags:['fork_below']},status:'visually_checked',conditionDetection:'human_checklist',instrument:null,photoRecorded:false,photoIncluded:false,co2Kg:null};
assert.equal(parseObservations(JSON.stringify({version:1,type:'field_observations',observations:[observation]}))[0].status,'requires_review');
assert.throws(()=>parseObservations(JSON.stringify({version:1,type:'field_observations',observations:[{...observation,co2Kg:999}]})));
assert.throws(()=>parseObservations('null'));
function fakeEnv(){const events=new EventTarget();return {isSecureContext:true,DeviceOrientationEvent:{requestPermission:async()=> 'granted'},now:()=>now,setTimeout:()=>1,clearTimeout:()=>{},addEventListener:events.addEventListener.bind(events),removeEventListener:events.removeEventListener.bind(events),emit:e=>events.dispatchEvent(e)};}
const env=fakeEnv(),hardware=new FieldHardware(env);let count=0;
await hardware.startSensor(()=>count++,()=>{});const event=new Event('deviceorientation');Object.assign(event,{beta:135,gamma:0});env.emit(event);assert.equal(count,1);hardware.stop();env.emit(event);assert.equal(count,1);assert.equal(hardware.samples.length,0);
await assert.rejects(new FieldHardware({...fakeEnv(),isSecureContext:false}).startSensor(()=>{},()=>{}),/HTTPS/);
await assert.rejects(new FieldHardware({...fakeEnv(),DeviceOrientationEvent:null}).startSensor(()=>{},()=>{}),/未提供/);
await assert.rejects(new FieldHardware({...fakeEnv(),DeviceOrientationEvent:{requestPermission:async()=> 'denied'}}).startSensor(()=>{},()=>{}),/未取得/);
await assert.rejects(new FieldHardware({...fakeEnv(),DeviceOrientationEvent:{requestPermission:async()=>{throw Error('platform error');}}}).startSensor(()=>{},()=>{}),/無法取得感測權限/);
let timeoutCallback,status='';const quiet=new FieldHardware({...fakeEnv(),setTimeout:fn=>{timeoutCallback=fn;return 1;}});await quiet.startSensor(()=>{},m=>status=m);timeoutCallback();assert.match(status,/沒有收到/);quiet.stop();
let resolvePermission;const pending=new FieldHardware({...fakeEnv(),DeviceOrientationEvent:{requestPermission:()=>new Promise(resolve=>resolvePermission=resolve)}});const request=pending.startSensor(()=>{},()=>{});pending.stop();resolvePermission('granted');await request;assert.equal(pending.listening,false);
let stopped=0;const tracks=[{stop:()=>stopped++,getSettings:()=>({facingMode:'environment'})}],stream={getTracks:()=>tracks,getVideoTracks:()=>tracks};
const camera=new FieldHardware({...fakeEnv(),mediaDevices:{getUserMedia:async opts=>{assert.equal(opts.audio,false);assert.equal(opts.video.facingMode.exact,'environment');return stream;}}});await camera.startCamera();camera.stop();assert.equal(stopped,1);
let resolveCamera;const pendingCamera=new FieldHardware({...fakeEnv(),mediaDevices:{getUserMedia:()=>new Promise(resolve=>resolveCamera=resolve)}});const pendingStream=pendingCamera.startCamera();pendingCamera.stop();resolveCamera(stream);assert.equal(await pendingStream,null);assert.equal(stopped,2);
console.log('PASS: rear-axis pitch, stability/freshness, general-angle geometry, abnormal-tree review gate, sensor provenance round-trip, permission and camera lifecycle.');
